with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , REFUND_PREMIUM as NET_REFUND_AMOUNT
        , cast(null as varchar) as REFUND_REASON
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as NET_REFUND_AMOUNT
        , REFUND_REASON as REFUND_REASON
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NET_REFUND_AMOUNT end) as NET_REFUND_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then REFUND_REASON end) as REFUND_REASON,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when NET_REFUND_AMOUNT is not null or REFUND_REASON is not null
                     then md5(upper(coalesce(cast(NET_REFUND_AMOUNT as varchar), '') || '|' || coalesce(cast(REFUND_REASON as varchar), '')))
                end as SAT_POLICY_REFUND_DETAIL_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_REFUND_DETAIL_HASHDIFF is not null
